// public IPv4 attacker addresses, most active first; private/reserved ranges dropped
const buckets = $input.first().json.aggregations?.ip?.buckets ?? [];
const reserved = /^(0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|22[4-9]\.|2[3-5]\d\.)/;
const ips = buckets.map(b => String(b.key)).filter(ip => /^\d{1,3}(\.\d{1,3}){3}$/.test(ip) && !reserved.test(ip));
if (!ips.length) return [];
return [{ json: { ips, ids: ips.map(ip => 'ip:' + ip) } }];

// skip: allowlisted, or checked in the last 7 days. At most 10 per run (AbuseIPDB free tier: 1,000/day)
const docs = $input.first().json.docs ?? [];
const ips = $('Collect attacker IPs').first().json.ips;
const known = {}; for (const d of docs) if (d.found) known[d._id] = d._source;
const week = 7 * 864e5, now = Date.now(), out = [];
for (const ip of ips) {
  const s = known['ip:' + ip];
  if (s && (s.verdict === 'allowlist' || (s.last_checked && now - Date.parse(s.last_checked) < week))) continue;
  const onlyGreyNoiseMissing = s?.abuseipdb && (s.errors ?? []).length > 0 && s.errors.every(e => e.startsWith('greynoise:'));
  if (onlyGreyNoiseMissing && s.last_checked && now - Date.parse(s.last_checked) < 2 * week) continue; // the backfill branch retries GreyNoise alone
  out.push({ json: { ip, first_seen: s?.first_seen ?? new Date().toISOString() } });
  if (out.length >= 10) break;
}
return out;

// one cached verdict per IP. Only facts from the providers are stored; failed lookups retry after 1 day
const picks = $('Pick IPs to check').all(), ab = $('AbuseIPDB').all(), gn = $('GreyNoise (community)').all(), ox = $('AlienVault OTX (IP)').all();
const nowIso = new Date().toISOString(), retryIso = new Date(Date.now() - 6 * 864e5).toISOString();
let ndjson = ''; const verdicts = [];
picks.forEach((p, i) => {
  const ip = p.json.ip, errors = [];
  const a = ab[i]?.json, g = gn[i]?.json, o = ox[i]?.json;
  const A = a?.statusCode === 200 ? a.body?.data : (errors.push('abuseipdb:' + (a?.statusCode ?? 'none')), null);
  const G = (g?.statusCode === 200 || g?.statusCode === 404) ? (g.body ?? {}) : (errors.push('greynoise:' + (g?.statusCode ?? 'none')), null);
  const O = o?.statusCode === 200 ? o.body : (errors.push('otx:' + (o?.statusCode ?? 'none')), null);
  const score = A?.abuseConfidenceScore ?? null, pulses = O?.pulse_info?.count ?? 0, cls = G?.classification ?? (G ? 'not_seen' : null);
  let verdict = (A || G || O) ? 'low' : 'unknown';
  if ((score ?? 0) >= 25 || pulses > 0) verdict = 'suspicious';
  if ((score ?? 0) >= 75 || cls === 'malicious') verdict = 'malicious';
  if (G?.riot === true || cls === 'benign') verdict = 'benign-scanner';
  const pl = O?.pulse_info?.pulses ?? [];
  const doc = {
    indicator: ip, indicator_type: 'ip', first_seen: p.json.first_seen,
    last_checked: (errors.length && !errors.every(e => e.startsWith('greynoise:'))) ? retryIso : nowIso, verdict, errors,
    abuseipdb: A ? { score, total_reports: A.totalReports, country: A.countryCode, isp: A.isp, usage_type: A.usageType, domain: A.domain } : undefined,
    greynoise: G ? { classification: cls, noise: !!G.noise, riot: !!G.riot, name: G.name ?? null, last_seen: G.last_seen ?? null } : undefined,
    otx: O ? { pulse_count: pulses, pulses: pl.slice(0, 10).map(x => x.name), tags: [...new Set(pl.flatMap(x => x.tags ?? []))].slice(0, 20) } : undefined,
  };
  ndjson += JSON.stringify({ index: { _id: 'ip:' + ip } }) + '\n' + JSON.stringify(doc) + '\n';
  verdicts.push({ ip, verdict, score, greynoise: cls, otx_pulses: pulses, errors: errors.join(',') });
});
return [{ json: { ndjson, checked: picks.length, verdicts } }];

// SHA-256 of files attackers dropped; only the hash ever leaves the lab, never the file
const b = $input.first().json.aggregations?.h?.buckets ?? [];
const items = b.filter(x => /^[0-9a-f]{64}$/.test(x.key)).map(x => ({ sha256: x.key, first_seen: x.f?.value_as_string, source: x.u?.buckets?.[0]?.key ?? null, filename: x.n?.buckets?.[0]?.key ?? null }));
if (!items.length) return [];
return [{ json: { items, ids: items.map(x => 'sha256:' + x.sha256) } }];

// known verdicts re-checked weekly, hashes VirusTotal did not know yet re-checked daily. Max 3 per run (VT: 4/min)
const docs = $input.first().json.docs ?? [];
const items = $('Collect hashes').first().json.items;
const known = {}; for (const d of docs) if (d.found) known[d._id] = d._source;
const now = Date.now(), out = [];
for (const it of items) {
  const s = known['sha256:' + it.sha256];
  const maxAge = (s?.verdict === 'unknown' ? 1 : 7) * 864e5;
  if (s && s.last_checked && now - Date.parse(s.last_checked) < maxAge) continue;
  out.push({ json: it });
  if (out.length >= 3) break;
}
return out;

const picks = $('Pick hashes to check').all(), vt = $('VirusTotal (hash)').all(), ox = $('AlienVault OTX (hash)').all();
const nowIso = new Date().toISOString(), retryIso = new Date(Date.now() - 6 * 864e5).toISOString();
let ndjson = ''; const verdicts = [];
picks.forEach((p, i) => {
  const h = p.json.sha256, errors = [];
  const v = vt[i]?.json, o = ox[i]?.json;
  const V = v?.statusCode === 200 ? v.body?.data?.attributes : null;
  if (!V && v?.statusCode !== 404) errors.push('virustotal:' + (v?.statusCode ?? 'none'));
  const O = o?.statusCode === 200 ? o.body : (errors.push('otx:' + (o?.statusCode ?? 'none')), null);
  const st = V?.last_analysis_stats ?? {};
  let verdict = V ? 'low' : 'unknown';
  if ((st.malicious ?? 0) >= 1) verdict = 'suspicious';
  if ((st.malicious ?? 0) >= 5) verdict = 'malicious';
  const family = V?.popular_threat_classification?.suggested_threat_label ?? null;
  const doc = {
    indicator: h, indicator_type: 'sha256', first_seen: p.json.first_seen, verdict, errors,
    last_checked: errors.length ? retryIso : nowIso,
    source: p.json.source, filename: p.json.filename,
    virustotal: V ? { malicious: st.malicious ?? 0, suspicious: st.suspicious ?? 0, undetected: st.undetected ?? 0, family, type: V.type_description ?? null,
                      names: (V.names ?? []).slice(0, 5), first_submission: V.first_submission_date ? new Date(V.first_submission_date * 1000).toISOString() : null }
                  : { known: false },
    otx: O ? { pulse_count: O.pulse_info?.count ?? 0, pulses: (O.pulse_info?.pulses ?? []).slice(0, 10).map(x => x.name) } : undefined,
  };
  ndjson += JSON.stringify({ index: { _id: 'sha256:' + h } }) + '\n' + JSON.stringify(doc) + '\n';
  verdicts.push({ sha256: h.slice(0, 16) + '...', verdict, detections: st.malicious ?? null, family, errors: errors.join(',') });
});
return [{ json: { ndjson, checked: picks.length, verdicts } }];

// up to 5 IPs per run whose only missing source is GreyNoise (keyless daily limit); nothing else is re-queried
const hits = $input.first().json.hits?.hits ?? [];
return hits.map(h => ({ json: { ip: h._source.indicator, doc: h._source } }));

// merge GreyNoise into the stored verdict and recalculate it; on another 429 just note the attempt (retry after ~20 h)
const list = $('GreyNoise backfill list').all(), gn = $('GreyNoise (backfill)').all(), nowIso = new Date().toISOString();
let ndjson = ''; const results = [];
list.forEach((it, i) => {
  const d = it.json.doc, g = gn[i]?.json, ok = g?.statusCode === 200 || g?.statusCode === 404;
  let doc;
  if (ok) {
    const G = g.body ?? {}, cls = G.classification ?? 'not_seen', score = d.abuseipdb?.score ?? 0, pulses = d.otx?.pulse_count ?? 0;
    let verdict = 'low';
    if (score >= 25 || pulses > 0) verdict = 'suspicious';
    if (score >= 75 || cls === 'malicious') verdict = 'malicious';
    if (G.riot === true || cls === 'benign') verdict = 'benign-scanner';
    doc = { greynoise: { classification: cls, noise: !!G.noise, riot: !!G.riot, name: G.name ?? null, last_seen: G.last_seen ?? null },
            errors: (d.errors ?? []).filter(e => !e.startsWith('greynoise:')), verdict, greynoise_attempt: nowIso };
    results.push({ ip: it.json.ip, greynoise: cls, verdict });
  } else {
    doc = { greynoise_attempt: nowIso };
    results.push({ ip: it.json.ip, greynoise: 'retry later (' + (g?.statusCode ?? 'none') + ')' });
  }
  ndjson += JSON.stringify({ update: { _id: 'ip:' + it.json.ip } }) + '\n' + JSON.stringify({ doc }) + '\n';
});
return [{ json: { ndjson, results } }];
